create or replace function public.guard_payment_request_transition() returns trigger language plpgsql security definer set search_path=public as $$ declare v_order public.orders; v_payment public.payments; begin if new.status in ('approved','completed','paid') then if new.related_payment_id is not null then select * into v_payment from public.payments where id=new.related_payment_id; if v_payment.id is null then raise exception 'Cannot approve payment request: related payment not found'; end if; end if; if new.reference is not null then select * into v_order from public.orders where payment_reference=new.reference limit 1; end if; if v_order.id is null and new.related_payment_id is not null then select * into v_payment from public.payments where id=new.related_payment_id; if v_payment.payment_reference is not null then select * into v_order from public.orders where payment_reference=v_payment.payment_reference limit 1; end if; end if; if v_order.id is null then raise exception 'Cannot approve payment request: authoritative order not found'; end if; if coalesce(new.amount,0) <> coalesce(v_order.total_amount,0) then raise exception 'Payment amount does not match authoritative order amount'; end if; end if; return new; end; $$;
